// Configuración del plan de artículos por marca. Lo llena Claude al instalar, con lo que diga la persona.
// blog: true solo si la marca tiene blog configurado en «SEO (borradores)».
// semillas: 5 a 20 frases que describen lo que vende la marca y los problemas de su público (sin nombres de marca).
// competidores: dominios de 2 o 3 competidores (sin https://). De ahí salen las keywords por las que ya posicionan.
// pais: location_code de DataForSEO (2484 = México) e idioma.
const MARCAS = {
  'marca-a': { nombre: 'Marca A', blog: true, dominio: '__DOMINIO_A__', gsc: '__GSC_SITIO_A__',
    semillas: [], competidores: [],
    publico: 'describe aquí a quién le vende la marca',
    reglas: 'Escribe aquí las reglas de la marca: temas que no se tocan, promesas que no se pueden hacer, tono.' },
  'marca-b': { nombre: 'Marca B', blog: false, dominio: '__DOMINIO_B__', gsc: '__GSC_SITIO_B__',
    semillas: [], competidores: [],
    publico: 'describe aquí a quién le vende la marca',
    reglas: 'Escribe aquí las reglas de la marca.' },
};
const AJUSTES = { location_code: 2484, language_code: 'es', pendientes_min: 4, temas_por_corrida: 8, min_volumen: 30, max_dificultad: 60 };
let probar = false;
try { probar = $('Probar').isExecuted === true; } catch (e) {}
const hoy = $now.setZone('America/Mexico_City').startOf('day');
return [{ json: { MARCAS, AJUSTES, probar, fecha: hoy.toISODate(), gsc: { ini: hoy.minus({ days: 30 }).toISODate(), fin: hoy.minus({ days: 3 }).toISODate() } } }];

// Planea solo las marcas con blog a las que les quedan menos temas pendientes que pendientes_min («Probar» planea todas).
const C = $('Marcas').first().json;
const filas = $('Leer seo_articulos').all().map(i => i.json || {}).filter(r => r.marca);
const PEND = ['planeado', 'preparando', 'por aprobar', 'cambios pedidos'];
const out = [];
for (const [marca, c] of Object.entries(C.MARCAS)) {
  if (!c.blog) continue;
  const pendientes = filas.filter(r => r.marca === marca && PEND.includes(r.estado)).length;
  if (!C.probar && pendientes >= C.AJUSTES.pendientes_min) continue;
  if (!(c.semillas || []).length && !(c.competidores || []).length) throw new Error('«SEO plan de artículos»: llena semillas o competidores de ' + c.nombre + ' en el nodo «Marcas».');
  out.push({ json: { marca, pendientes, faltan: Math.max(1, C.AJUSTES.temas_por_corrida) } });
}
return out;

// Por marca: ideas de keywords a partir de las semillas y keywords por las que posiciona cada competidor.
const C = $('Marcas').first().json, A = C.AJUSTES;
const out = [];
for (const it of $input.all()) {
  const m = it.json.marca, c = C.MARCAS[m];
  const sem = (c.semillas || []).map(s => String(s).trim().toLowerCase()).filter(Boolean).slice(0, 20);
  if (sem.length) out.push({ json: { marca: m, tipo: 'ideas', url: 'https://api.dataforseo.com/v3/dataforseo_labs/google/keyword_ideas/live',
    body: [{ keywords: sem, location_code: A.location_code, language_code: A.language_code, limit: 300, order_by: ['keyword_info.search_volume,desc'] }] } });
  for (const d of (c.competidores || []).slice(0, 3)) out.push({ json: { marca: m, tipo: 'competidor', competidor: d, url: 'https://api.dataforseo.com/v3/dataforseo_labs/google/ranked_keywords/live',
    body: [{ target: String(d).replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''), location_code: A.location_code, language_code: A.language_code, limit: 200,
      filters: [['ranked_serp_element.serp_item.rank_group', '<=', 20]], order_by: ['keyword_data.keyword_info.search_volume,desc'] }] } });
}
return out;

// Búsquedas donde la marca ya aparece (28 días): las que están entre la posición 8 y 40 son oportunidad.
const C = $('Marcas').first().json;
return $('¿Qué marcas planear?').all().map(i => ({ json: { marca: i.json.marca,
  url: 'https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(C.MARCAS[i.json.marca].gsc) + '/searchAnalytics/query',
  body: { startDate: C.gsc.ini, endDate: C.gsc.fin, dimensions: ['query'], rowLimit: 500 } } }));

// Junta las keywords candidatas por marca, quita lo que no sirve para un artículo y lo que ya existe,
// les pone un puntaje de oportunidad y arma el pedido a Claude.
const C = $('Marcas').first().json, A = C.AJUSTES;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
const palabras = s => new Set(norm(s).split(' ').filter(w => w.length > 2 && !['para', 'los', 'las', 'del', 'que', 'con', 'una', 'por', 'como', 'que'].includes(w)));
const parecidas = (a, b) => { const x = palabras(a), y = palabras(b); if (!x.size || !y.size) return false; let n = 0; x.forEach(w => { if (y.has(w)) n++; }); return n / Math.min(x.size, y.size) >= 0.8; };
const existentes = $('Leer seo_articulos').all().map(i => i.json || {}).filter(r => r.marca);
const pedidosD = $('Pedidos a DataForSEO').all().map(i => i.json), respD = $('DataForSEO').all().map(i => i.json || {});
const pedidosG = $('Pedidos a Search Console').all().map(i => i.json), respG = $('Search Console').all().map(i => i.json || {});
const kwTab = ((($('Leer Keywords').first().json || {}).values) || []).slice(1);
let costo = 0;
const errores = [];
const salida = [];
for (const it of $('¿Qué marcas planear?').all()) {
  const m = it.json.marca, c = C.MARCAS[m];
  const cand = new Map();
  const marcaPropia = norm(c.nombre);
  const ajenas = (c.competidores || []).map(d => norm(String(d).replace(/^https?:\/\//, '').replace(/^www\./, '').split('.')[0])).filter(x => x.length > 2);
  const add = (kw, x) => {
    const k = norm(kw);
    if (!k || k.split(' ').length < 2 && !(x.volumen >= 1000)) return; // una sola palabra casi nunca es un artículo
    if (ajenas.some(a => k.includes(a)) || (marcaPropia && k.includes(marcaPropia))) return; // marcas: no son artículos
    const y = cand.get(k) || { keyword: k, volumen: null, dificultad: null, cpc: null, intencion: '', fuentes: [], impresiones: 0, posicion: null };
    for (const f of ['volumen', 'dificultad', 'cpc']) if (y[f] == null && x[f] != null) y[f] = x[f];
    if (!y.intencion && x.intencion) y.intencion = x.intencion;
    if (x.impresiones) { y.impresiones = x.impresiones; y.posicion = x.posicion; }
    if (!y.fuentes.includes(x.fuente)) y.fuentes.push(x.fuente);
    cand.set(k, y);
  };
  pedidosD.forEach((p, i) => {
    if (p.marca !== m) return;
    const t = ((respD[i] || {}).tasks || [])[0] || {};
    costo += Number(t.cost || 0);
    if (t.status_code !== 20000) { errores.push(c.nombre + ' · ' + (p.competidor || 'ideas') + ': ' + (t.status_message || (respD[i].error && respD[i].error.message) || 'sin respuesta')); return; }
    for (const x of (((t.result || [])[0] || {}).items || [])) {
      const d = p.tipo === 'ideas' ? x : (x.keyword_data || {});
      const info = d.keyword_info || {}, prop = d.keyword_properties || {}, int = d.search_intent_info || {};
      add(d.keyword, { volumen: info.search_volume ?? null, cpc: info.cpc ?? null, dificultad: prop.keyword_difficulty ?? null, intencion: int.main_intent || '', fuente: p.tipo === 'ideas' ? 'ideas' : 'competencia: ' + p.competidor });
    }
  });
  pedidosG.forEach((p, i) => {
    if (p.marca !== m) return;
    const r = respG[i] || {};
    if (r.error) { errores.push(c.nombre + ' · Search Console: ' + (r.error.message || 'error')); return; }
    for (const x of r.rows || []) if (x.position >= 8 && x.position <= 40 && x.impressions >= 20) add(x.keys[0], { impresiones: x.impressions, posicion: Math.round(x.position * 10) / 10, fuente: 'search console' });
  });
  for (const r of kwTab) if (r[1] === m && r[2]) add(r[2], { volumen: r[5] === '' || r[5] == null ? null : Number(r[5]), cpc: r[6] === '' || r[6] == null ? null : Number(r[6]), fuente: 'research semanal' });
  const deMarca = existentes.filter(r => r.marca === m);
  const lista = [...cand.values()]
    .filter(x => ['navigational', 'transactional'].indexOf(x.intencion) === -1)
    .filter(x => (x.volumen != null && x.volumen >= A.min_volumen) || x.impresiones >= 20)
    .filter(x => x.dificultad == null || x.dificultad <= A.max_dificultad)
    .filter(x => !deMarca.some(r => parecidas(r.keyword, x.keyword)))
    .map(x => Object.assign(x, { puntaje: Math.round(((x.volumen || x.impresiones * 3) * (1 - (x.dificultad || 30) / 100)) * (x.impresiones ? 1.5 : 1)) }))
    .sort((a, b) => b.puntaje - a.puntaje)
    .slice(0, 60);
  if (!lista.length) { errores.push(c.nombre + ': no salieron keywords candidatas (revisa semillas y competidores).'); continue; }
  const ya = deMarca.map(r => ({ keyword: r.keyword, titulo: r.titulo || '', estado: r.estado }));
  const prompt = `Marca: ${c.nombre} (${c.dominio}). Público: ${c.publico}.\nReglas de la marca (obligatorias): ${c.reglas}\n\n` +
    `Tarea: escoge hasta ${it.json.faltan} temas de artículo para el blog de esta marca, en orden de prioridad, usando SOLO keywords de la lista de candidatas. ` +
    'Prioriza oportunidad (puntaje: volumen alto y dificultad baja; las de Search Console ya tienen impresiones) y que el artículo le sirva al público de la marca. ' +
    'Cada artículo usa una keyword principal y puede cubrir keywords secundarias muy parecidas de la misma lista. ' +
    'No propongas dos artículos que respondan la misma búsqueda ni uno que repita o compita con los que ya existen (lista de abajo). ' +
    'El tema es un brief de 1 a 3 frases: qué debe explicar, para quién y qué no inventar (sin cifras, precios ni datos que no estén en fuentes oficiales; si algo no está confirmado, decirlo). ' +
    'intencion: informativa, comercial, comparativa o b2b. Escribe en español de México.\n' +
    'Responde SOLO con JSON válido: {"temas":[{"keyword":"","secundarias":[""],"tema":"","intencion":"","por_que":""}]}\n\n' +
    'Candidatas:\n' + JSON.stringify(lista.map(x => ({ keyword: x.keyword, volumen: x.volumen, dificultad: x.dificultad, impresiones: x.impresiones || undefined, posicion: x.posicion || undefined, puntaje: x.puntaje }))) +
    '\n\nArtículos que ya existen (no repetir):\n' + JSON.stringify(ya);
  salida.push({ json: { marca: m, nombre: c.nombre, lista, prompt, faltan: it.json.faltan } });
}
if (!salida.length) throw new Error('«SEO plan de artículos» no encontró candidatas. ' + errores.join(' · ').slice(0, 400));
return salida.map((s, i) => ({ json: Object.assign(s.json, { costo: i === 0 ? Math.round(costo * 10000) / 10000 : 0, errores: i === 0 ? errores : [] }) }));

// Valida lo que escogió Claude (solo keywords de la lista, sin repetidas) y arma las filas «planeado».
const J = $('Juntar candidatos').all().map(i => i.json), R = $('Claude escoge').all().map(i => i.json || {});
const existentes = $('Leer seo_articulos').all().map(i => i.json || {});
let orden = existentes.reduce((m, r) => Math.max(m, Number(r.orden) || 0), 0);
const ahora = $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd HH:mm');
const porMarca = [], fallas = [...(J[0] ? J[0].errores : [])];
J.forEach((j, i) => {
  const r = R[i] || {};
  if (r.error || !r.content) { fallas.push(j.nombre + ': Claude no respondió (' + ((r.error && r.error.message) || 'sin respuesta') + ')'); return; }
  const txt = r.content.filter(b => b.type === 'text').map(b => b.text).join('');
  let temas = [];
  try { const m = txt.match(/\{[\s\S]*\}/); temas = JSON.parse(m ? m[0] : txt).temas || []; } catch (e) { fallas.push(j.nombre + ': respuesta de Claude no legible'); return; }
  const porKw = new Map(j.lista.map(x => [x.keyword, x]));
  const usadas = new Set();
  const filas = [];
  for (const t of temas) {
    const k = String(t.keyword || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
    const x = porKw.get(k);
    if (!x || usadas.has(k) || !t.tema) continue;
    usadas.add(k);
    filas.push({ marca: j.marca, keyword: x.keyword, tema: String(t.tema).slice(0, 900), intencion: ['informativa', 'comercial', 'comparativa', 'b2b'].includes(t.intencion) ? t.intencion : 'informativa',
      volumen: x.volumen, dificultad: x.dificultad, cpc: x.cpc,
      notas: ('Plan ' + ahora.slice(0, 10) + ': ' + String(t.por_que || '') + ((t.secundarias || []).length ? ' · Secundarias: ' + t.secundarias.join(', ') : '') + ' · Fuente: ' + x.fuentes.join(', ')).slice(0, 900) });
    if (filas.length >= j.faltan) break;
  }
  porMarca.push(filas);
});
// Intercala las marcas para que el blog no publique solo de una.
const out = [];
for (let k = 0; porMarca.some(f => f[k]); k++) for (const f of porMarca) if (f[k]) out.push(Object.assign({}, f[k], { orden: ++orden, estado: 'planeado', version: 0, actualizado: ahora }));
if (!out.length) throw new Error('«SEO plan de artículos» no pudo armar temas. ' + fallas.join(' · ').slice(0, 400));
return out.map((x, i) => ({ json: Object.assign(x, i === 0 ? { _fallas: fallas } : {}) }));

const F = $('Armar filas').all().map(i => i.json);
const C = $('Marcas').first().json;
const J = $('Juntar candidatos').first().json;
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = n => n == null ? '—' : Number(n).toLocaleString('es-MX');
let t = '📝 <b>Plan de artículos</b>' + (C.probar ? ' (prueba)' : '') + '\n' + F.length + ' temas nuevos en seo_articulos, en el orden en que se escriben:\n';
F.forEach((x, i) => { t += '\n' + (i + 1) + '. <b>' + e(x.keyword) + '</b> · ' + e((C.MARCAS[x.marca] || {}).nombre || x.marca) + ' · ' + num(x.volumen) + ' búsquedas/mes' + (x.dificultad != null ? ' · dificultad ' + x.dificultad : '') + '\n   ' + e(String(x.tema).slice(0, 160)); });
const fallas = F[0]._fallas || [];
if (fallas.length) t += '\n\n⚠️ ' + e(fallas.join(' · ').slice(0, 500));
t += '\n\nCosto DataForSEO: US$' + (J.costo || 0) + '. Los borradores llegan aquí para aprobar; nada se publica sin tu ✅. Para quitar un tema, cámbialo a «descartado» en la tabla.';
return [{ json: { texto: t.slice(0, 4000) } }];
